const input = $input.first().json;

// ── FIX: data arrives nested under 'body' from webhook ──
const raw = input.body || input;

const get = (key) => {
  return raw[key] 
    || raw?.properties?.[key]?.value 
    || raw?.properties?.[key] 
    || input[key]
    || '';
};

const firstName     = get('firstName') || get('firstname');
const lastName      = get('lastName') || get('lastname');
const email         = get('email');
const website       = get('website');
const reasonForCall = get('reasonForCall') || get('reason_for_call');
const decisionMaker = get('decisionMaker') || get('decision_maker');
const annualRevenue = get('annualRevenue') || get('annual_revenue');
const numberOfEmployees = parseInt(get('numberOfEmployees') || get('numberofemployees')) || 0;
const message       = get('message');
const contactId     = raw.id || raw.contactId || input.id || '';

let score = 0;
const breakdown = [];

// ── REASON FOR CALL (30pts) ──────────────────────────
const reasonScores = {
  'AI Transformation': 30,
  'Custom AI Engineer': 20,
  'Reselling/White-label': 15,
  'Educating Team': 10
};
const reasonPts = reasonScores[reasonForCall] || 0;
score += reasonPts;
breakdown.push(`Reason (${reasonForCall}): +${reasonPts}pts`);

// ── ANNUAL REVENUE (25pts) ───────────────────────────
const revenueScores = {
  '$5M - $10M': 25,
  '$1M - $5M': 20,
  '$10M+': 20,
  '$500K - $1M': 10,
  '$100K - $500K': 5,
  'Under $100K': 0,
  'Prefer not to say': 5
};
const revenuePts = revenueScores[annualRevenue] || 0;
score += revenuePts;
breakdown.push(`Revenue (${annualRevenue}): +${revenuePts}pts`);

// ── DECISION MAKER (20pts) ───────────────────────────
const dmPts = decisionMaker === 'Yes' ? 20 : 0;
score += dmPts;
breakdown.push(`Decision Maker (${decisionMaker}): +${dmPts}pts`);

// ── EMPLOYEE COUNT (15pts) ───────────────────────────
let empPts = 0;
if (numberOfEmployees >= 10 && numberOfEmployees <= 150) empPts = 15;
else if (numberOfEmployees > 150) empPts = 8;
else if (numberOfEmployees > 0) empPts = 5;
score += empPts;
breakdown.push(`Employees (${numberOfEmployees || 'not provided'}): +${empPts}pts`);

// ── EMAIL QUALITY (5pts) ─────────────────────────────
const genericDomains = ['gmail.com','yahoo.com','hotmail.com','outlook.com','icloud.com'];
const emailDomain = email.split('@')[1]?.toLowerCase() || '';
const emailPts = !genericDomains.includes(emailDomain) ? 5 : 0;
score += emailPts;
breakdown.push(`Business email: +${emailPts}pts`);

// ── NOTE: Message quality scored by AI in next node ──
// Max hard score = 95, AI adds up to 10 (total possible = 105, capped at 100)

// ── BUCKET (pre-AI, will be recalculated after AI node) ──
let bucket = 'cold';
if (score >= 65) bucket = 'hot';
else if (score >= 38) bucket = 'warm';

return [{
  json: {
    contactId,
    firstName,
    lastName,
    email,
    website,
    reasonForCall,
    decisionMaker,
    annualRevenue,
    numberOfEmployees,
    message,
    hardScore: score,
    preBucket: bucket,
    breakdown: breakdown.join(' | ')
  }
}];

const prev = $('⚡ Score Lead (Hard Fields)').first().json;
const aiInput = $input.first().json;

// jsonOutput:true means OpenAI returns parsed JSON directly on the node output
let aiData = { messageScore: 0, painPoint: 'Not specified' };
try {
  if (aiInput?.messageScore !== undefined) {
    // Direct parsed JSON from jsonOutput:true
    aiData = { messageScore: aiInput.messageScore, painPoint: aiInput.painPoint || 'Not specified' };
  } else if (aiInput?.message?.content) {
    // Fallback: nested content string
    const cleaned = aiInput.message.content.replace(/```json|```/g, '').trim();
    aiData = JSON.parse(cleaned);
  } else if (aiInput?.text) {
    const cleaned = aiInput.text.replace(/```json|```/g, '').trim();
    aiData = JSON.parse(cleaned);
  }
} catch(e) {
  // fallback to defaults
}

const totalScore = Math.min(100, prev.hardScore + aiData.messageScore);

let bucket = 'cold';
if (totalScore >= 70) bucket = 'hot';
else if (totalScore >= 40) bucket = 'warm';

return [{
  json: {
    ...prev,
    messageScore: aiData.messageScore,
    painPoint: aiData.painPoint,
    totalScore,
    bucket,
    fullBreakdown: prev.breakdown + ` | Message quality: +${aiData.messageScore}pts | TOTAL: ${totalScore}/100 → ${bucket.toUpperCase()}`
  }
}];
